package lk.ac.sliit.ridelink.ride.infrastructure.client.fare;
import com.github.tomakehurst.wiremock.WireMockServer; import lk.ac.sliit.ridelink.ride.application.usecase.ExternalServiceException; import lk.ac.sliit.ridelink.ride.domain.enums.VehicleType; import org.junit.jupiter.api.*; import org.springframework.http.client.SimpleClientHttpRequestFactory; import org.springframework.web.client.RestClient; import java.math.BigDecimal; import static com.github.tomakehurst.wiremock.client.WireMock.*; import static org.junit.jupiter.api.Assertions.*;
class FarePaymentServiceClientTest {WireMockServer server;FarePaymentServiceClient client;@BeforeEach void start(){server=new WireMockServer(0);server.start();client=new FarePaymentServiceClient(RestClient.builder().baseUrl(server.baseUrl()).requestFactory(new SimpleClientHttpRequestFactory()).build());}@AfterEach void stop(){server.stop();}
 @Test void readsFareEstimateAndSendsStableContract(){server.stubFor(post("/api/fares/estimate").willReturn(okJson("{\"totalFare\":1250.50}")));assertEquals(new BigDecimal("1250.50"),client.estimate(VehicleType.CAR,new BigDecimal("10")));server.verify(postRequestedFor(urlEqualTo("/api/fares/estimate")).withRequestBody(equalToJson("{\"vehicleType\":\"CAR\",\"distanceKm\":10}")));}
 @Test void mapsFareServerFailure(){server.stubFor(post("/api/fares/estimate").willReturn(serverError()));assertThrows(ExternalServiceException.class,()->client.estimate(VehicleType.CAR,BigDecimal.TEN));}
 @Test void finalFareUsesCurrentCompatibleCalculationContract(){server.stubFor(post("/api/fares/estimate").willReturn(okJson("{\"totalFare\":1300}")));assertEquals(new BigDecimal("1300"),client.finalFare(VehicleType.CAR,BigDecimal.TEN));}
}
